// app/hifz/surahs.ts — single source of truth for the FULL Quran
// (Phase 2, 2026-11-21: expanded from the 43-surah launch set to all
// 114 surahs, 6,236 ayahs. Generated by tools/gen_full_quran.py from
// the live Quran.com chapters + juz APIs — do not hand-edit; re-run
// the script instead. The 43 launch-set slugs are
// preserved exactly so existing URLs never move. Names and
// meanings always come from Quran.com name_simple /
// translated_name (fixed 2026-11-21: the launch set had
// stored English meanings as `name` and ayah counts as
// `meaning` for some surahs).
//
// Ayah counts, Arabic names, transliterations and revelation verified
// against the Quran.com chapters API (https://api.quran.com/api/v4/chapters,
// live fetch 2026-11-21). English meanings follow Quran.com's
// translated_name, lightly tidied. Juz numbers follow the Quran.com juz
// API verse_mapping (https://api.quran.com/api/v4/juzs).
// Slugs: lowercase hyphenated transliteration, no "surah" prefix.

export type Revelation = 'Makki' | 'Madani';

export interface HifzSurah {
  /** Surah number (1–114). */
  id: number;
  /** URL slug, e.g. "al-mulk" -> /hifz/al-mulk. */
  slug: string;
  /** Arabic name. */
  arabic: string;
  /** Transliterated name. */
  name: string;
  /** English meaning. */
  meaning: string;
  /** Number of ayahs — verified against the Quran.com chapters API. */
  ayahCount: number;
  revelation: Revelation;
  /** Juz the surah starts in. */
  juz: number;
  /** Juz the surah ends in, when it spans two juz. */
  juzEnd?: number;
}

