/** All surahs keyed by slug. */
export const ALL_SURAHS_BY_SLUG: Record<string, HifzSurah> =
  Object.fromEntries(ALL_SURAHS.map((s) => [s.slug, s]));

/** The six featured surahs, in hub display order. */
export const FEATURED_SURAHS: HifzSurah[] = [
  'al-fatihah',
  'al-mulk',
  'ya-sin',
  'ar-rahman',
  'al-waqiah',
  'al-kahf',
].map((slug) => ALL_SURAHS_BY_SLUG[slug]);

/** Juz Amma surahs (78–114), in mushaf order. */
export const JUZ_AMMA_SURAHS: HifzSurah[] = ALL_SURAHS.filter(
  (s) => s.juz === 30,
);

/**
 * Ayat al-Kursi (2:255) — a single-ayah study page, not a surah page.
 * Canonical ayah URL: /hifz/al-baqarah/2-255 ; friendly page: /hifz/ayat-al-kursi.
 */
export const AYAT_AL_KURSI = {
  surahId: 2,
  surahSlug: 'al-baqarah',
  surahName: 'Al-Baqarah',
  ayah: 255,
  /** Friendly page slug. */
  slug: 'ayat-al-kursi',
  /** Ayah ref used in the URL: /hifz/al-baqarah/2-255. */
  ref: '2-255',
  /** Canonical ayah key shown in content and metadata. */
  key: '2:255',
} as const;

export function getSurahBySlug(slug: string): HifzSurah | undefined {
  return ALL_SURAHS_BY_SLUG[slug];
}

export function getSurahById(id: number): HifzSurah | undefined {
  return ALL_SURAHS.find((s) => s.id === id);
}

/** Total ayahs in the whole Quran: 6,236. */
export const TOTAL_AYAH_COUNT: number =
  ALL_SURAHS.reduce((sum, s) => sum + s.ayahCount, 0);

